import csv
from collections import defaultdict

def calculate_bonus(employee_id, project_hours, deliverables):
    bonus = 0

    total_project_hours = sum(project_hours.values())

    for pid, hours in project_hours.items():
        project_deliverables = deliverables[pid]
        fraction = hours / total_project_hours

        bonus += fraction * project_deliverables['revenue']

    bonus *= (1 / len(employee_id))
    return bonus

def allocate_bonus(bonus_pool):
    employees = {}
    projects = defaultdict(list)
    project_hours = {}
    deliverables = {}

    with open('../../carrow-advisory-9/data/bonus_employees.csv') as f:
        next(f)
        for row in csv.reader(f):
            e_id, name, role, department, salary, start_date, end_date = row
            e = {'name': name, 'role': role, 'department': department,
                 'salary': float(salary)}
            employees[e_id] = e

    with open('../../carrow-advisory-9/data/bonus_projects.csv') as f:
        next(f)
        for row in csv.reader(f):
            p_id, revenue, start_month, end_month = row
            projects[p_id] = {'revenue': float(revenue),
                               'start_month': int(start_month),
                               'end_month': int(end_month)}

    with open('../../carrow-advisory-9/data/bonus_project_hours.csv') as f:
        next(f)
        for row in csv.reader(f):
            e_id, p_id, month, hours = row
            project_hours.setdefault(p_id, {})
            project_hours[p_id][month] = int(hours)

    deliverables = projects

    for e_id in employees:
        bonus = calculate_bonus(e_id, project_hours, deliverables)
        print(f'({e_id}, {employees[e_id]["name"]}): {bonus:.2f}')

    return 0

if __name__ == '__main__':
    allocate_bonus(100000)

