delimiter $$
CREATE FUNCTION calculate_bonus() RETURNS JSON
BEGIN
  DECLARE bonus_per_emp FLOAT DEFAULT 5000;
  DECLARE avg_bonus FLOAT;
  DECLARE grand_total_bonus FLOAT;
  DECLARE emp_bonus FLOAT;
  DECLARE bonus REAL;

  SET grand_total_bonus = bonus_per_emp * (SELECT COUNT(DISTINCT employee) FROM HOURS_BY_MONTH);

  SELECT AVG(amount) INTO avg_bonus FROM APPENGINE.Bonuses;

  SET bonus = grand_total_bonus / avg_bonus;

  UPDATE APPENGINE.Bonuses SET amount = bonus;

  RETURN JSON_OBJECT(
    'sid',
    @sid,
    'bonus_json',
    HISTO-GRAP-ES[0].disp_json,
    'app_context',
    REGEXP_REPLACE(@app_context, '\\n', '<br>')
  );
END$$

