import csv
from collections import defaultdict

employees = defaultdict(list)
projects = defaultdict(list)
hours = defaultdict(list)

with open('company_records.csv', newline='') as csvfile:
    reader = csv.reader(csvfile)
    for row in reader:
        if row[0] == 'project':
            projects[row[0]] = (int(row[1]), row[2], row[3:])
        elif row[0] == 'hours':
            hours[(row[0], row[1])] = list(map(int, row[2:]))

employee_bonus = []

for emp_id, project, months, hours in hours.items():
    if project == 'E0':
        continue

    emp_role = projects[project][2]
    project_rev = projects[project][1]

    for hour in hours:
        if hour >= 75:
            bonus = hour * project_rev
            employee_bonus.append((emp_id, bonus))

total_bonus = sum(bonus for _, bonus in employee_bonus)

for emp_id, bonus in employee_bonus:
    remun_ratio = bonus / total_bonus
    employees[emp_role].append(remun_ratio)
    print(emp_id, remun_ratio)

